"""Embed the shared catalog in the single-file macOS executable."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
catalog = json.loads((root / "Shared/explain.json").read_text())
quote = lambda text: json.dumps(text, ensure_ascii=False)
lines = [
    "// Generated by scripts/generate-prompts.py from Shared/explain.json.",
    "enum ExplainCatalog {",
    "    struct Profile {",
    "        let en, zh, hintEn, hintZh: String",
    "    }",
]
for field in ("base", "general", "custom"):
    for lang in ("en", "zh"):
        lines.append(f"    static let {field}{lang.title()} = {quote(catalog[field][lang])}")
lines.append("    static let profiles = [")
for profile in catalog["profiles"]:
    args = ", ".join(f"{key}: {quote(profile[key])}" for key in ("en", "zh", "hintEn", "hintZh"))
    lines.append(f"        Profile({args}),")
lines.extend(["    ]", "}", ""])
(root / "Sources/AskAI/ExplainCatalog.swift").write_text("\n".join(lines))
